from sympy import divisors

def t(k):
    # Return the largest odd divisor of k
    for d in reversed(divisors(k)):
        if d % 2 == 1:
            return d

def check_a(a, max_n=100):
    # For a given a, check if there exists n such that all differences are divisible by 4
    for n in range(1, max_n+1):
        ok = True
        for i in range(a):
            diff = t(n+a+i) - t(n+i)
            if diff % 4 != 0:
                ok = False
                break
        if ok:
            return True
    return False

# Check for odd a up to 25
results = []
for a in range(1, 26, 2):
    if check_a(a):
        results.append(a)

print("Possible odd values of a (1 to 25):", results)
